-- ============================================================================
-- DATA SEED: PT Nusantara Mart Retailindo (retail_fmcg_db)
-- Modul         : SQL for Data Analyst - Studi Kasus 1 (Retail FMCG)
-- Target RDBMS  : PostgreSQL 16
-- Deskripsi     : Injeksi data realistis ritel FMCG lengkap dengan anomali bisnis:
--                 1. Anomali Teks (spasi liar, mixed-case pada kategori & kota)
--                 2. Anomali Nilai NULL pada diskon_nominal
--                 3. Anomali Kuantitas (nol / negatif)
--                 4. Anomali Orphaned Records (produk_id tak terdaftar di master)
--                 5. Anomali Double-Click Kasir (transaksi_id terduplikasi)
-- ============================================================================

BEGIN;

SET search_path TO public;

-- Bersihkan data lama jika ada
TRUNCATE fact_penjualan_detail, fact_penjualan_header, dim_pelanggan, dim_toko, dim_produk RESTART IDENTITY CASCADE;

